  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Compound 6, a morpholine- and pyrimidine-containing analogue with high assay-transfer, showed high brain penetration in rat with a B/P ratio of 2.4, supporting meaningful CNS access for the query's morpholine/heteroaromatic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "MTX-241F, an aminopyrimidine-fused heteroaromatic inhibitor, achieved micromolar murine brain concentrations and was characterized as brain-penetrant, supporting the query's aminopyrimidine/thienopyrimidine core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Compound 40 showed a brain/plasma AUC ratio of 2.2 and inhibited brain Hsp90 after oral dosing in mice, demonstrating functional CNS exposure for a closely related aminopyrimidine-fused heteroaromatic.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "SHP099, an aminopyrimidine with a basic amine, maintained a brain-plasma ratio >1 from 1 h to 24 h after oral dosing, supporting sustained CNS access for similar heteroaromatic kinase inhibitors.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "1-NA-PP1, a systemically administered kinase inhibitor with an aminopyrimidine-like core, crossed the BBB and reached brain concentrations sufficient for target inhibition, supporting the query's likely brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Compound 8, an aminopyrimidine/morpholine amide analogue, showed poor brain penetration with a Bu/Pu ratio of 0.11, providing a caution that some close analogues can be efflux-limited; its lower transfer score and additional amide/trifluoromethyl aniline features reduce direct applicability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "CZC25146, a morpholine- and aminopyrimidine-containing compound, showed negligible total brain/plasma AUC in mice, but its extra aniline sulfonamide and polar substituents make it less transferable to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: multiple high-transfer analogues with aminopyrimidine, fused heteroaromatic, and morpholine features demonstrate meaningful brain penetration (B/P >1, brain target engagement), outweighing lower-transfer negative analogues with additional polar amide/sulfonamide liabilities.",
  "evidence_gaps": [
    "No direct brain/plasma, CSF, or unbound brain measurement exists for the exact query molecule; prediction relies on transferable analogue evidence.",
    "Efflux-transporter status of the query is not directly measured; some close analogues show low unbound brain fractions."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

